do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Adobe$q$,$q$public_company$q$),($q$Allscripts Healthcare Solutions$q$,$q$public_company$q$),($q$Ampere Computing$q$,$q$private_company$q$),($q$Arcadia Solutions$q$,$q$private_company$q$),($q$Cerner$q$,$q$public_company$q$),($q$Cisco$q$,$q$public_company$q$),($q$Epic Systems$q$,$q$private_company$q$),($q$Hewlett-Packard Enterprise$q$,$q$public_company$q$),($q$IBM$q$,$q$public_company$q$),($q$InterSystems$q$,$q$private_company$q$),($q$SAP$q$,$q$public_company$q$),($q$Salesforce$q$,$q$public_company$q$),($q$TikTok USDS Joint Venture$q$,$q$private_company$q$),($q$Workday$q$,$q$public_company$q$),($q$athenahealth$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$For example, following our acquisition of Cerner Corporation, we also face competition from large healthcare IT providers such as Allscripts Healthcare Solutions, Inc., Arcadia Solutions, athenahealth, Inc., Epic Systems Corporation and InterSystems Corporation, among others.$q$),(2,$q$OCI’s multicloud services work with a number of our competitors’ products, including Microsoft Azure, Amazon Web Services and Google Cloud.$q$),(3,$q$Our enterprise cloud, software and hardware offerings compete directly with certain offerings from some of the largest and most competitive companies in the world, including Adobe Systems Incorporated, Alphabet Inc., Amazon.com, Inc., Cisco Systems, Inc., Intel Corporation, International Business Machines Corporation, Microsoft Corporation, Salesforce, Inc. and SAP SE, as well as other companies like Hewlett-Packard Enterprise and Workday, Inc.$q$),(4,$q$The majority of the non-marketable debt and equity investments we held as of May 31, 2025 were with Ampere Computing Holdings LLC (Ampere), an equity method investee.$q$),(5,$q$The substantial majority of the non-marketable investments we held as of May 31, 2026
 were with TikTok USDS Joint Venture LLC, an equity method investee in which we have an ownership interest of 
15
%.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$competes$q$,$q$ORCL$q$,$q$Adobe$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$competes$q$,$q$ORCL$q$,$q$Alphabet$q$,$q${3,2}$q$::int[],$q${business,risk_factors}$q$::text[],null,null,null,null),(3,$q$competes$q$,$q$ORCL$q$,$q$Amazon$q$,$q${3,2}$q$::int[],$q${business,risk_factors}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$ORCL$q$,$q$Cisco$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(5,$q$competes$q$,$q$ORCL$q$,$q$Intel$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$ORCL$q$,$q$IBM$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(7,$q$competes$q$,$q$ORCL$q$,$q$Microsoft$q$,$q${3,2}$q$::int[],$q${business,risk_factors}$q$::text[],null,null,null,null),(8,$q$competes$q$,$q$ORCL$q$,$q$Salesforce$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(9,$q$competes$q$,$q$ORCL$q$,$q$SAP$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(10,$q$competes$q$,$q$ORCL$q$,$q$Hewlett-Packard Enterprise$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$ORCL$q$,$q$Workday$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(12,$q$competes$q$,$q$ORCL$q$,$q$Allscripts Healthcare Solutions$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$ORCL$q$,$q$Arcadia Solutions$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$ORCL$q$,$q$athenahealth$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$ORCL$q$,$q$Epic Systems$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$ORCL$q$,$q$InterSystems$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(17,$q$acquires$q$,$q$ORCL$q$,$q$Cerner$q$,$q${1}$q$::int[],$q${business}$q$::text[],null,null,null,null),(18,$q$invests$q$,$q$ORCL$q$,$q$Ampere Computing$q$,$q${4}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(19,$q$invests$q$,$q$ORCL$q$,$q$TikTok USDS Joint Venture$q$,$q${5}$q$::int[],$q${notes}$q$::text[],15,$q$exact$q$,$q$source_revenue$q$,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$ORCL$q$ then ticker=$q$ORCL$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$ORCL M6 group 2-4$q$,'claude-sonnet-5-5',213686,6815,0.692,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1341439/000119312526277521/orcl-20260531.htm$q$,r.sec[k],t,true,$q$2026-06-22$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
